package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class FastMath_max_TriageGen2Test {

    private static final float DELTA = 1e-7f;

    @Test
    public void testMax_aLessThanB() {
        // Covers (a <= b) branch where a < b
        assertEquals(5.0f, FastMath.max(1.0f, 5.0f), DELTA);
    }

    @Test
    public void testMax_aEqualsB() {
        // Covers (a <= b) branch where a == b
        assertEquals(5.0f, FastMath.max(5.0f, 5.0f), DELTA);
    }

    @Test
    public void testMax_aGreaterThanB_Normal() {
        // Covers (a <= b) is false, and (Float.isNaN(a + b)) is false
        // Note: The logic in the provided method: (a <= b) ? b : (Float.isNaN(a+b) ? NaN : b)
        // This implementation is unusual because if a > b, it returns b (unless NaN).
        // We test the path where a > b and result is b.
        assertEquals(2.0f, FastMath.max(10.0f, 2.0f), DELTA);
    }

    @Test
    public void testMax_aGreaterThanB_NaNResult() {
        // Covers (a <= b) is false, and (Float.isNaN(a + b)) is true
        // To get NaN from a + b where a > b, we can use Infinity and -Infinity
        // However, Infinity + (-Infinity) is NaN.
        // Let a = Infinity, b = -Infinity. a > b is true. a + b is NaN.
        float a = Float.POSITIVE_INFINITY;
        float b = Float.NEGATIVE_INFINITY;
        assertEquals(Float.NaN, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_WithNaN() {
        // If a is NaN, (a <= b) is false.
        // If b is NaN, (a <= b) is false.

        // Case 1: a is NaN, b is 5.0. (NaN <= 5.0) is false. NaN + 5.0 is NaN. Returns NaN.
        assertEquals(Float.NaN, FastMath.max(Float.NaN, 5.0f), 0.0f);

        // Case 2: a is 5.0, b is NaN. (5.0 <= NaN) is false. 5.0 + NaN is NaN. Returns NaN.
        assertEquals(Float.NaN, FastMath.max(5.0f, Float.NaN), 0.0f);

        // Case 3: Both NaN. (NaN <= NaN) is false. NaN + NaN is NaN. Returns NaN.
        assertEquals(Float.NaN, FastMath.max(Float.NaN, Float.NaN), 0.0f);
    }

    @Test
    public void testMax_NegativeValues() {
        assertEquals(-1.0f, FastMath.max(-5.0f, -1.0f), DELTA);
        assertEquals(-5.0f, FastMath.max(-1.0f, -5.0f), DELTA);
    }
}
